#include "st_big_curve.h"
#include "st_bgi_trig.h"
#include "io_error.h"
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#define CHECK(x) do { if (!(x)) { fprintf(stderr,"%s:%d: %s\n",__FILE__,__LINE__,#x); exit(1); } } while (0)
/* Literal DDO1021..10d5 WORDs from the retained curve-contract-data, not
 * generated by an emulator or a host floating-point sine function. */
static const uint16_t quadrant[91]={
	0x0000,0x023b,0x0477,0x06b2,0x08ed,0x0b27,0x0d61,0x0f99,0x11d0,0x1406,
	0x163a,0x186c,0x1a9c,0x1ccb,0x1ef7,0x2120,0x2348,0x256c,0x278d,0x29ac,
	0x2bc7,0x2ddf,0x2ff3,0x3203,0x340f,0x3618,0x381c,0x3a1c,0x3c17,0x3e0e,
	0x4000,0x41ec,0x43d4,0x45b6,0x4793,0x496a,0x4b3c,0x4d08,0x4ecd,0x508d,
	0x5246,0x53f9,0x55a6,0x574b,0x58ea,0x5a82,0x5c13,0x5d9c,0x5f1f,0x609a,
	0x620d,0x6379,0x64dd,0x6639,0x678d,0x68d9,0x6a1d,0x6b59,0x6c8c,0x6db7,
	0x6ed9,0x6ff3,0x7104,0x720c,0x730b,0x7401,0x74ef,0x75d3,0x76ad,0x777f,
	0x7847,0x7906,0x79bc,0x7a68,0x7b0a,0x7ba3,0x7c32,0x7cb8,0x7d33,0x7da5,
	0x7e0e,0x7e6c,0x7ec1,0x7f0b,0x7f4c,0x7f83,0x7fb0,0x7fd3,0x7fec,0x7ffb,
	0x8000,
};
static int32_t signed_word(uint16_t value) { return value<32768?(int32_t)value:(int32_t)value-65536; }
static int32_t sine_oracle(int32_t angle)
{
	int sign=angle<0?-1:1;
	unsigned degree=(unsigned)(angle<0?-angle:angle)%360;
	if (degree>=180) { degree-=180; sign=-sign; }
	if (degree>90) degree=180-degree;
	return sign*(int32_t)quadrant[degree]*2;
}
static uint16_t product_oracle(int32_t coefficient, uint16_t radius)
{
	int64_t product=(int64_t)coefficient*radius;
	int64_t quotient=product>=0?product/65536:-((-product+65535)/65536);
	return (uint16_t)quotient;
}
static uint16_t metric_oracle(uint16_t x_word, uint16_t y_word)
{
	int32_t x=signed_word(x_word),y=signed_word(y_word),result;
	if (y_word==32768) result=x>=0?x+6000-32768:x+4000+32768;
	else if (x>=0) result=y<=0?-y-x:x+6000-y;
	else result=y<=0?-x+2000+y:x+4000+y;
	return (uint16_t)result;
}
static void trigonometry(void)
{
	for (unsigned degree=0;degree<=90;++degree) CHECK(st_bgi_sin32((int)degree)==2*(int32_t)quadrant[degree]);
	for (unsigned angle=0;angle<=65535;++angle) {
		CHECK(st_big_curve_sin((uint16_t)angle)==sine_oracle(signed_word((uint16_t)angle)));
		CHECK(st_big_curve_cos((uint16_t)angle)==sine_oracle(signed_word((uint16_t)(angle+90))));
		CHECK(st_bgi_sin32((int)signed_word((uint16_t)angle))==sine_oracle(signed_word((uint16_t)angle)));
	}
	CHECK(st_big_curve_sin(32768)==-9120 && st_big_curve_cos(32767)==64728);
	CHECK(st_bgi_sin32(32767+90)==65046); /* RIP keeps its wide angle addition. */
	CHECK(st_bgi_sin32(INT_MAX)==sine_oracle(INT_MAX%360));
	CHECK(st_bgi_sin32(INT_MIN)==sine_oracle(INT_MIN%360));
	static const int32_t coefficients[]={0,1142,-1142,65536,-65536,INT32_MAX,INT32_MIN};
	for (size_t i=0;i<sizeof(coefficients)/sizeof(coefficients[0]);++i) for (unsigned radius=0;radius<=65535;++radius)
		CHECK((uint16_t)st_bgi_trig_mul(coefficients[i],(uint16_t)radius)==product_oracle(coefficients[i],(uint16_t)radius));
	CHECK(st_bgi_trig_mul(1142,1000)==17 && st_bgi_trig_mul(-1142,1000)==-18);
	CHECK((uint16_t)st_bgi_trig_mul(65536,32768)==32768);
}
static void endpoint_bits(void)
{
	static const struct { uint16_t angle,rx,ry,x,y; } points[]={
		{0,1,1,1,0},{1,1,1,0,0},{120,1,1,65535,0},{150,1,1,65535,0},
		{0,0,1,0,0},{90,0,1,0,65535},{1,1000,1000,999,(uint16_t)-17},
		{65535,1000,1000,999,18},{32767,1000,1000,987,(uint16_t)-121}
	};
	for (size_t i=0;i<sizeof(points)/sizeof(points[0]);++i) {
		uint16_t x=(uint16_t)st_bgi_trig_mul(st_big_curve_cos(points[i].angle),points[i].rx);
		uint16_t y=(uint16_t)(0u-(uint16_t)st_bgi_trig_mul(st_big_curve_sin(points[i].angle),points[i].ry));
		CHECK(x==points[i].x && y==points[i].y);
	}
}
static void metrics(void)
{
	static const uint16_t boundaries[]={0,1,32767,32768,32769,65535};
	for (unsigned word=0;word<=65535;++word) for (size_t i=0;i<sizeof(boundaries)/sizeof(boundaries[0]);++i) {
		CHECK(st_big_curve_metric((uint16_t)word,boundaries[i])==metric_oracle((uint16_t)word,boundaries[i]));
		CHECK(st_big_curve_metric(boundaries[i],(uint16_t)word)==metric_oracle(boundaries[i],(uint16_t)word));
	}
	CHECK(st_big_curve_metric(0,32768)==(uint16_t)-26768);
	CHECK(st_big_curve_metric(10,0)==65526 && st_big_curve_metric(0,10)==5990);
	CHECK(st_big_curve_metric(65526,0)==2010 && st_big_curve_metric(0,65526)==10);
}
static void aspects(void)
{
	static const unsigned defaults[]={4500,7750,10000};
	for (unsigned radius=0;radius<=65535;++radius) for (size_t mode=0;mode<3;++mode) {
		uint16_t result=17;
		CHECK(st_big_curve_aspect((uint16_t)radius,(uint16_t)defaults[mode],10000,&result)==0);
		CHECK(result==(uint16_t)((uint64_t)radius*defaults[mode]/10000));
	}
	static const struct { uint16_t radius,x,y,result; } cases[]={
		{20,4500,10000,9},{20,7750,10000,15},{20,10000,10000,20},
		{32768,10000,10000,32768},{65535,32768,65535,32768},{65535,32767,1,32769},
		{20,7750,(uint16_t)-10000,(uint16_t)-15},{1,(uint16_t)-4500,10000,0},
		{65535,32768,32768,65535},{0,65535,1,0}
	};
	for (size_t i=0;i<sizeof(cases)/sizeof(cases[0]);++i) {
		uint16_t result=0; CHECK(st_big_curve_aspect(cases[i].radius,cases[i].x,cases[i].y,&result)==0 && result==cases[i].result);
	}
	uint16_t result=0x1234;
	CHECK(st_big_curve_aspect(20,7750,0,&result)==IO_ERROR_OUT_OF_RANGE && result==0x1234);
	CHECK(st_big_curve_aspect(0,0,0,&result)==IO_ERROR_OUT_OF_RANGE && result==0x1234);
	CHECK(st_big_curve_aspect(20,7750,10000,NULL)==IO_ERROR_INVALID_ARGUMENT);
}
int main(void) { trigonometry(); endpoint_bits(); metrics(); aspects(); return 0; }
